import pyomo.environ as pyo

DATA = {
    "products": ["full", "semi"],
    "price": {"full": 2800, "semi": 2400},
    "chips_per_unit": {"full": 20, "semi": 15},
    "chips_available": 3500,
    "hours_per_unit": {"full": 1.2, "semi": 1.2},
    "hours_available": 6.0,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    products = d["products"]

    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=products)

    model.production = pyo.Var(
        model.P,
        domain=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["price"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def chips_rule(m):
        return sum(
            d["chips_per_unit"][p] * m.production[p] for p in m.P
        ) <= d["chips_available"]

    model.chips_limit = pyo.Constraint(rule=chips_rule)

    def hours_rule(m):
        return sum(
            d["hours_per_unit"][p] * m.production[p] for p in m.P
        ) <= d["hours_available"]

    model.hours_limit = pyo.Constraint(rule=hours_rule)

    return model
